class Graph {
    private java.util.List<int[]>[] adj;
    private int n;
    public Graph(int n, int[][] edges) {
        this.n = n; adj = new java.util.List[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) adj[e[0]].add(new int[]{e[1], e[2]});
    }
    public void addEdge(int[] edge) { adj[edge[0]].add(new int[]{edge[1], edge[2]}); }
    public int shortestPath(int node1, int node2) {
        int[] dist = new int[n]; java.util.Arrays.fill(dist, Integer.MAX_VALUE); dist[node1] = 0;
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> a[1] - b[1]);
        pq.offer(new int[]{node1, 0});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            if (cur[1] > dist[cur[0]]) continue;
            if (cur[0] == node2) return cur[1];
            for (int[] next : adj[cur[0]]) {
                int nd = cur[1] + next[1];
                if (nd < dist[next[0]]) { dist[next[0]] = nd; pq.offer(new int[]{next[0], nd}); }
            }
        }
        return -1;
    }
}

class Graph {
    private int[][] dist;
    private int n;
    public Graph(int n, int[][] edges) {
        this.n = n;
        dist = new int[n][n];
        for (int i = 0; i < n; i++) {
            java.util.Arrays.fill(dist[i], Integer.MAX_VALUE);
            dist[i][i] = 0;
        }
        for (int[] e : edges) {
            dist[e[0]][e[1]] = e[2];
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (dist[i][k] != Integer.MAX_VALUE && dist[k][j] != Integer.MAX_VALUE) {
                        dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
                    }
                }
            }
        }
    }
    public void addEdge(int[] edge) {
        if (edge[2] >= dist[edge[0]][edge[1]]) return;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][edge[0]] != Integer.MAX_VALUE && dist[edge[1]][j] != Integer.MAX_VALUE) {
                    long nd = (long) dist[i][edge[0]] + edge[2] + dist[edge[1]][j];
                    if (nd < dist[i][j]) {
                        dist[i][j] = (int) nd;
                    }
                }
            }
        }
    }
    public int shortestPath(int node1, int node2) {
        return dist[node1][node2] == Integer.MAX_VALUE ? -1 : dist[node1][node2];
    }
}
